# 0: walk to kitchen to find the coffeepot
	walk('kitchen')
	# 1: find and grab the coffeepot
	find('coffeepot')
	assert('close' to 'coffeepot')
		else: find('coffeepot')
	grab('coffeepot')
	# 2: walk to living room where the coffee table is located
	walk('livingroom')
	# 3: find the coffee table
	find('coffeetable')
	# 4: put the coffeepot on the coffee table
	assert('coffeepot' in 'hands')
		else: walk('kitchen')
		else: find('coffeepot')
		else: grab('coffeepot')
	assert('close' to 'coffeetable')
		else: find('coffeetable')
	putin('coffeepot', 'coffeetable')
	# 5: go back to kitchen to find the cupcake
	walk('kitchen')
	# 6: find and grab the cupcake
	find('cupcake')
	assert('close' to 'cupcake')
		else: find('cupcake')
	grab('cupcake')
	# 7: return to living room coffee table
	walk('livingroom')
	find('coffeetable')
	# 8: put the cupcake on the coffee table next to the coffeepot
	assert('cupcake' in 'hands')
		else: walk('kitchen')
		else: find('cupcake')
		else: grab('cupcake')
	assert('close' to 'coffeetable')
		else: find('coffeetable')
	putin('cupcake', 'coffeetable')
	# 9: verify both items are on the coffee table
	lookat('coffeetable')
	assert('coffeepot' in 'coffeetable')
		else: find('coffeepot')
		else: grab('coffeepot')
		else: putin('coffeepot', 'coffeetable')
	assert('cupcake' in 'coffeetable')
		else: find('cupcake')
		else: grab('cupcake')
		else: putin('cupcake', 'coffeetable')
	# 10: Done

